;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; ECS Entity Creation and Destruction System for MSX
;; Generated by MSX Retro Game IDE
;;
;; High-level entity management using templates
;; Depends on ecs_memory_manager.asm
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;

; Include memory manager
INCLUDE "ecs_memory_manager.asm"

; Template loading state
CURRENT_TEMPLATE_PTR:   DW 0    ; Pointer to current template being processed

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Create entity from template
;; Input: HL = Pointer to entity template
;; Output: A = Entity ID (0xFF if failed)
;; Destroys: BC, DE, HL
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
CREATE_ENTITY_FROM_TEMPLATE:
    LD (CURRENT_TEMPLATE_PTR), HL
    
    ; Allocate entity
    CALL ALLOCATE_ENTITY
    CP 0xFF
    RET Z                   ; Failed to allocate entity
    
    PUSH AF                 ; Save entity ID
    
    ; Get component count from template
    LD HL, (CURRENT_TEMPLATE_PTR)
    LD B, (HL)              ; B = component count
    INC HL                  ; Point to first component
    
    ; Process each component in template
CREATE_ENTITY_COMPONENTS_LOOP:
    LD A, B
    OR A
    JR Z, CREATE_ENTITY_SUCCESS
    
    PUSH BC
    PUSH HL
    
    ; Read component type ID
    LD D, (HL)              ; D = component type ID
    INC HL
    
    ; Allocate component
    LD A, D                 ; Component type ID
    LD B, (SP+4)            ; Entity ID (from saved value)
    CALL ALLOCATE_COMPONENT
    CP 0xFF
    JR Z, CREATE_ENTITY_FAIL
    
    ; Copy component data from template
    LD C, A                 ; C = component index
    CALL GET_COMPONENT_PTR  ; HL = component data area
    INC HL                  ; Skip type ID
    INC HL                  ; Skip entity owner, point to data area
    LD DE, HL               ; DE = destination (component data)
    POP HL                  ; HL = source (template data)
    LD BC, 14               ; Copy 14 bytes of component data
    LDIR
    
    PUSH HL                 ; Save template pointer
    POP BC                  ; Restore loop counter
    DJNZ CREATE_ENTITY_COMPONENTS_LOOP

CREATE_ENTITY_SUCCESS:
    POP AF                  ; Return entity ID
    RET

CREATE_ENTITY_FAIL:
    ; Cleanup: free the entity and any allocated components
    POP HL                  ; Clean stack
    POP BC
    POP AF                  ; Get entity ID
    CALL FREE_ENTITY
    LD A, 0xFF              ; Return failure
    RET

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Create entity from template ID
;; Input: A = Template ID (index in templates table)
;; Output: A = Entity ID (0xFF if failed)
;; Destroys: BC, DE, HL
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
CREATE_ENTITY_BY_TEMPLATE_ID:
    ; Get template pointer from table
    LD B, A                 ; B = template ID
    LD HL, ENTITY_TEMPLATES_TABLE
    ADD A, A                ; * 2 (word size)
    ADD A, L
    LD L, A
    JR NC, CREATE_ENTITY_BY_ID_NO_CARRY
    INC H
CREATE_ENTITY_BY_ID_NO_CARRY:
    LD E, (HL)              ; Get template pointer low
    INC HL
    LD D, (HL)              ; Get template pointer high
    LD HL, DE               ; HL = template pointer
    
    ; Check for null pointer (end of table)
    LD A, H
    OR L
    LD A, 0xFF
    RET Z                   ; Return failure if null
    
    ; Create entity from template
    JP CREATE_ENTITY_FROM_TEMPLATE

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Destroy entity completely
;; Input: A = Entity ID
;; Output: None
;; Destroys: BC, HL
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
DESTROY_ENTITY:
    ; Check if entity is valid and active
    LD B, A
    CALL GET_ENTITY_PTR
    LD A, (HL)              ; Get active flag
    OR A
    RET Z                   ; Entity not active, nothing to do
    
    ; Free the entity (this also removes all components)
    LD A, B
    CALL FREE_ENTITY
    RET

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Find entity by component type
;; Input: A = Component type ID
;; Output: A = Entity ID (0xFF if not found), HL = Component pointer
;; Destroys: BC, DE
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
FIND_ENTITY_BY_COMPONENT:
    LD D, A                 ; D = target component type
    LD B, 0                 ; B = current entity ID
    
FIND_ENTITY_LOOP:
    LD A, B
    CP MAX_ENTITIES
    JR NC, FIND_ENTITY_NOT_FOUND
    
    ; Check if entity is active
    CALL GET_ENTITY_PTR
    LD A, (HL)              ; Get active flag
    OR A
    JR Z, FIND_ENTITY_NEXT  ; Skip inactive entity
    
    ; Check entity's components
    INC HL                  ; Point to component count
    LD C, (HL)              ; C = component count
    INC HL                  ; Point to component list
    
FIND_ENTITY_CHECK_COMPONENTS:
    LD A, C
    OR A
    JR Z, FIND_ENTITY_NEXT  ; No more components
    
    LD A, (HL)              ; Get component index
    PUSH BC
    PUSH HL
    LD C, A
    CALL GET_COMPONENT_PTR  ; HL = component pointer
    LD A, (HL)              ; Get component type
    CP D                    ; Compare with target type
    JR Z, FIND_ENTITY_FOUND
    
    POP HL
    POP BC
    INC HL                  ; Next component
    DEC C
    JR FIND_ENTITY_CHECK_COMPONENTS

FIND_ENTITY_NEXT:
    INC B                   ; Next entity
    JR FIND_ENTITY_LOOP

FIND_ENTITY_FOUND:
    POP DE                  ; Clean stack
    POP DE
    LD A, B                 ; Return entity ID
    ; HL already points to component
    RET

FIND_ENTITY_NOT_FOUND:
    LD A, 0xFF              ; Return not found
    LD HL, 0
    RET

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Get component from entity
;; Input: A = Entity ID, B = Component type ID
;; Output: HL = Component pointer (0 if not found)
;; Destroys: BC, DE
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
GET_ENTITY_COMPONENT:
    LD E, B                 ; E = target component type
    LD B, A                 ; B = entity ID
    CALL GET_ENTITY_PTR
    
    ; Check if entity is active
    LD A, (HL)
    OR A
    JR Z, GET_COMPONENT_NOT_FOUND
    
    ; Get component list
    INC HL                  ; Point to component count
    LD C, (HL)              ; C = component count
    INC HL                  ; Point to component list
    
GET_COMPONENT_SEARCH:
    LD A, C
    OR A
    JR Z, GET_COMPONENT_NOT_FOUND
    
    LD A, (HL)              ; Get component index
    PUSH BC
    PUSH HL
    LD C, A
    CALL GET_COMPONENT_PTR  ; HL = component pointer
    LD A, (HL)              ; Get component type
    CP E                    ; Compare with target type
    JR Z, GET_COMPONENT_FOUND
    
    POP HL
    POP BC
    INC HL                  ; Next component
    DEC C
    JR GET_COMPONENT_SEARCH

GET_COMPONENT_FOUND:
    POP DE                  ; Clean stack
    POP DE
    INC HL                  ; Skip type ID
    INC HL                  ; Skip entity owner, point to data
    RET

GET_COMPONENT_NOT_FOUND:
    LD HL, 0
    RET

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Add component to existing entity
;; Input: A = Entity ID, B = Component type ID
;; Output: HL = Component pointer (0 if failed)
;; Destroys: BC, DE
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
ADD_COMPONENT_TO_ENTITY:
    PUSH AF
    LD A, B                 ; Component type
    LD B, (SP)              ; Entity ID (from stack)
    CALL ALLOCATE_COMPONENT
    CP 0xFF
    JR Z, ADD_COMPONENT_FAIL
    
    ; Return component data pointer
    LD C, A
    CALL GET_COMPONENT_PTR
    INC HL                  ; Skip type ID
    INC HL                  ; Skip entity owner, point to data
    POP AF                  ; Clean stack
    RET

ADD_COMPONENT_FAIL:
    POP AF
    LD HL, 0
    RET

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Remove component from entity
;; Input: A = Entity ID, B = Component type ID
;; Output: None
;; Destroys: BC, DE, HL
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
REMOVE_COMPONENT_FROM_ENTITY:
    LD E, B                 ; E = target component type
    LD B, A                 ; B = entity ID
    CALL GET_ENTITY_PTR
    
    ; Check if entity is active
    LD A, (HL)
    OR A
    RET Z                   ; Entity not active
    
    ; Get component list
    INC HL                  ; Point to component count
    LD C, (HL)              ; C = component count
    INC HL                  ; Point to component list
    LD D, 0                 ; D = component position
    
REMOVE_COMPONENT_SEARCH:
    LD A, C
    OR A
    RET Z                   ; Component not found
    
    LD A, (HL)              ; Get component index
    PUSH AF
    PUSH BC
    PUSH HL
    LD C, A
    CALL GET_COMPONENT_PTR  ; HL = component pointer
    LD A, (HL)              ; Get component type
    CP E                    ; Compare with target type
    JR Z, REMOVE_COMPONENT_FOUND
    
    POP HL
    POP BC
    POP AF
    INC HL                  ; Next component
    INC D                   ; Next position
    DEC C
    JR REMOVE_COMPONENT_SEARCH

REMOVE_COMPONENT_FOUND:
    POP HL                  ; HL = component list position
    POP BC                  ; C = remaining components
    POP AF                  ; A = component index to free
    
    ; Free the component
    PUSH BC
    PUSH HL
    CALL FREE_COMPONENT
    POP HL
    POP BC
    
    ; Shift remaining components left
    PUSH HL
    LD B, A                 ; B = entity ID (from earlier)
    CALL GET_ENTITY_PTR
    INC HL                  ; Point to component count
    DEC (HL)                ; Decrease component count
    POP HL                  ; HL = component list position
    
    ; Shift components
    DEC C                   ; C = components to shift
    LD A, C
    OR A
    RET Z                   ; No components to shift
    
    LD DE, HL               ; DE = destination
    INC HL                  ; HL = source (next component)
    LD B, C                 ; B = count
REMOVE_COMPONENT_SHIFT:
    LD A, (HL)
    LD (DE), A
    INC HL
    INC DE
    DJNZ REMOVE_COMPONENT_SHIFT
    
    RET